def neutral_background(apps, schema_editor):
    """Poster-first design: a background still on the old violet-tinted default becomes neutral."""
    SiteSettings = apps.get_model("cms", "SiteSettings")
    for site in SiteSettings.objects.all():
        if (site.background_color or "").upper() in {"#0B0917", "#07060B", "#08051A"}:
            site.background_color = "#0C0C0F"
            site.save(update_fields=["background_color"])
    from django.core.cache import cache

    cache.delete("cms:site-settings")  # SiteSettings.load() caches the row


